public class WorkerTask implements Runnable {
    private final String taskName;

    public WorkerTask(String taskName) {
        this.taskName = taskName;
    }

    @Override
    public void run() {
        System.out.println(Thread.currentThread().getName() + " executing: " + taskName);
        try {
            Thread.sleep(100);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public static void main(String[] args) {
        Thread t1 = new Thread(new WorkerTask("Task-A"), "Worker-1");
        Thread t2 = new Thread(new WorkerTask("Task-B"), "Worker-2");

        t1.start();
        t2.start();
    }
}
